class Solution:
    def jump(self, nums: List[int]) -> int:
        jumps = 0
        current_end = 0
        next_end = 0
        for i in range(len(nums) - 1):
            next_end = max(next_end, i + nums[i])
            if i == current_end:
                jumps += 1
                current_end = next_end
                if current_end >= len(nums) - 1:
                    break
        return jumps

