from typing import List

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        tails = []
        for num in nums:
            low, high = 0, len(tails)
            while low < high:
                mid = (low + high) // 2
                if tails[mid] < num:
                    low = mid + 1
                else:
                    high = mid
            idx = low
            if idx == len(tails):
                tails.append(num)
            else:
                tails[idx] = num
        return len(tails)

