class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []
        result = []
        queue = [root]
        while queue:
            level_size = len(queue)
            rightmost_val = None
            for _ in range(level_size):
                node = queue.pop(0)
                rightmost_val = node.val
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            result.append(rightmost_val)
        return result

