class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m = len(matrix)
        n = len(matrix[0])
        left, right = 0, m * n - 1

        while left <= right:
            mid = (left + right) // 2
            row = mid // n
            col = mid % n
            current = matrix[row][col]
            if current == target:
                return True
            elif current < target:
                left = mid + 1
            else:
                right = mid - 1
        return False

