class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        len1 = len(s1)
        len2 = len(s2)
        if len1 > len2:
            return False

        count_s1 = [0] * 26
        count_window = [0] * 26

        for c in s1:
            count_s1[ord(c) - ord('a'] += 1

        # Initialize the first window
        for i in range(len1):
            c = s2[i]
            count_window[ord(c) - ord('a'] += 1

        if count_s1 == count_window:
            return True

        # Slide the window
        for i in range(len1, len2):
            left_char = s2[i - len1]
            right_char = s2[i]

            # Update counts
            count_window[ord(left_char) - ord('a'] -= 1
            count_window[ord(right_char) - ord('a'] += 1

            if count_s1 == count_window:
                return True

        return False

