class Solution:
    def minCameraCover(self, root: Optional[TreeNode]) -> int:
        self.count = 0

        def helper(node):
            if not node:
                return 0  # covered
            left = helper(node.left)
            right = helper(node.right)
            if left == -1 or right == -1:
                self.count += 1
                return 1  # current node has a camera
            elif left == 1 or right == 1:
                return 0  # covered by child
            else:
                return -1  # not covered, need parent to cover

        root_state = helper(root)
        if root_state == -1:
            self.count += 1
        return self.count
